// Compose a readable alert from the error payload: workflow, node, message, execution link.
const e = $json;
const err = (e.execution && e.execution.error) || {};
const failedNode = (err.node && err.node.name) || 'unknown node';
const execRef = (e.execution && (e.execution.url || e.execution.id)) || 'n/a';

return [{ json: {
  subject: '[email-to-order demo] Workflow failed: ' + ((e.workflow && e.workflow.name) || 'unknown workflow'),
  text: 'Workflow: ' + ((e.workflow && e.workflow.name) || 'unknown') + '\n' +
        'Failed node: ' + failedNode + '\n' +
        'Error: ' + (err.message || 'unknown error') + '\n' +
        'Execution: ' + execRef + '\n' +
        'Time: ' + new Date().toISOString()
} }];
